questionvariables.text:
/* 1. Linear Scale Factor (k) : prototype -> industrial tank */
k: 5 + rand(6);                 /* k between 5 and 10 */

/* 2. Prototype (Object) dimensions */
r_p: rand(3) + 2;               /* Radius 2..4 m */
h_p: rand(4) + 6;               /* Cylindrical height 6..9 m */

/* 3. Prototype volume = cylinder + hemisphere (exact, with %pi) */
vol_cyl:  %pi * r_p^2 * h_p;
vol_hemi: (2/3) * %pi * r_p^3;
vol_p_exact: vol_cyl + vol_hemi;

/* Display strings for the worked solution (2 d.p. numeric pieces) */
dispVcyl:  decimalplaces(float(vol_cyl), 2);
dispVhemi: decimalplaces(float(vol_hemi), 2);

/* 4. Scale factors */
asf: k^2;                       /* Area Scale Factor  */
vsf: k^3;                       /* Volume Scale Factor */

/* 5. Teacher answers */
ta1: asf;                                        /* Area Scale Factor        */
ta2: vsf;                                        /* Volume Scale Factor       */
ta3: decimalplaces(float(vol_p_exact), 2);       /* Prototype volume (2 d.p.) */
ta4: decimalplaces(ta3 * vsf, 2);                /* Industrial volume (2 d.p.)*/

/* 6. Helper values for targeted (wrong-answer) feedback */
wrong_vol_asf: decimalplaces(ta3 * asf, 2);      /* used ASF instead of VSF   */
